def rootwords(i,extra=()):return list(dict.fromkeys([w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED and '-' not in w]+list(extra)))
def rootexclude(i):
 r=ASSIGN['roots'][i];c=CATALOG[r['id']];return {w:DEFERRED[w] for w in set(r['family'])|set(c['family'])|set(c['words'])|set(c['unmatched']) if w in DEFERRED}
FLACC_ROOT=dict(id='C0431',meaning='松垮；失去张力',core='像一片本来能挺起的叶子，忽然软软地垂了下来。',image='拉丁 flaccus → flaccidus → 法语 flaccide 或直接借入 → 英语 flaccid。',intro='这一组先记 flaccid：身体或植物缺乏张力，也可以比喻文章没有力度。柔软本身可以舒服，flaccid 却常让人看见该撑住的东西没撑住。',forms='flacc- 来自拉丁语，不是现代英语 flap 或 slack 的缩写；更远词源未完全明确。常见读法中 cc 读 /s/。',branches=[['物体松弛与表达无力','flaccid']],contrasts='soft 常中性，flaccid 通常多出松弛、乏力的感觉。意思相近的 flabby 不因此自动成为同一条借词链上的前后阶段。',practice='分别用 flaccid 描写一株植物和一段文字，说明什么东西在两个场景里“撑不起来”。',words=rootwords(268),exclude=rootexclude(268))
LACER_ROOT=dict(id='C0642',meaning='撕裂；割伤',core='表面被扯开，留下看得见的裂口；尖锐的话也可以像这样伤人。',image='拉丁 lacer → lacerare；分词 laceratus → 中古英语 laceraten → lacerate；名词 laceratio 经法语等 → laceration。',intro='lacerate 是割裂、撕伤这个动作，也可说严厉批评；laceration 是撕裂过程或留下的一道伤口。两个英语词对应得很整齐，但名词有自己的借入历史。',forms='现代可以用 lacerate 与 laceration 配对记忆；-ation 对应动作或结果名词。不要从 lace 花边反推 lacer- 的来源。',branches=[['动作与尖锐攻击','lacerate'],['过程与伤口','laceration']],contrasts='scratch 通常强调刮擦，bruise 是淤伤，laceration 则强调组织被割开、撕开。词源不能代替对具体伤情的判断。',practice='把一句含 lacerate 的事故描述改成含 laceration 的伤口描述，再用 lacerate 写一次措辞尖锐的评论。',words=rootwords(269),exclude=rootexclude(269))
SUD_ROOT=dict(id='C1450',meaning='汗；出汗；向外渗出',core='内部的液体透到表面，这个画面也能说一个人的气质自然流露。',image='拉丁 sudare → exsudare／exudare → exude；远同源的日耳曼旁支 → 古英语 swat、swætan → sweat → sweaty、sweater、sweatshirt、sweatpants、sweatshop。',intro='exude 常出现在 exude confidence 这样的人物描写中。sweat 一支更日常：身体出汗、费力工作、运动衣物，甚至血汗工厂。sweat 与拉丁 sud- 是远亲，不能把英语词画成拉丁借词一步步改字母的结果。',forms='sweat 的 ea 读 /e/，与 sweet 的 /iː/ 不同。sweater 的 -er 早期可以指人或使人出汗的东西，后来才形成衣物名称；sweatpants 保留复数形式。',branches=[['渗出与流露','exude'],['身体感觉与费力','sweat, sweaty'],['运动服装进入日常','sweater, sweatshirt, sweatpants'],['过度榨取劳动','sweatshop']],contrasts='sweater 通常是毛衣、针织衫，sweatshirt 是卫衣式运动休闲上衣。sweatshop 不只是一个很热的工厂，重点在低薪、差条件和劳工压榨。',practice='解释 exude confidence 为什么不必真的有液体，再用 sweater 与 sweatshirt 写两种穿着；指出 sweat 的日耳曼路线与 sudare 的拉丁路线在哪里分开。',words=rootwords(270),exclude=rootexclude(270))
PAUC_ROOT=dict(id='C0974',meaning='少；数量不多',core='数一数，只有那么几个；要强调“不够”还是“还有一些”，得看具体措辞。',image='拉丁 paucus → paucitas → 法语 paucité 等 → paucity；远同源日耳曼支线 → 古英语 feawe／fea → few → fewer、fewest。',intro='paucity 是正式地说匮乏，few 是基础的数量词。few、fewer、fewest 分别说少、更少、最少；few 前加 a，往往把焦点从太少转为还存在几个。',forms='pauc- 与 few 不属于现代英语可自由替换的拼写规则，而是长期分化的同源形态。few 接可数复数；比较级 -er 和最高级 -est 在这里都表示数量比较。',branches=[['正式表达不足','paucity'],['日常数量及比较','few, fewer, fewest']],contrasts='a few 不等于 few 的所有语气，quite a few 常表示相当不少。less 常配不可数数量，也能用于作为整体看待的时间、距离和金额，不能机械地把所有复数单位前的 less 判错。',practice='写出 few options 与 a few options 的语气差别，再把两组方案数量比较改成含 fewer 的句子，最后在三组中指出 the fewest。',words=rootwords(271),exclude=rootexclude(271))
MOLL_ROOT=dict(id='C0757',meaning='软；使柔软、缓和',core='硬绷绷的东西软下来，紧绷的态度也可以松下来。',image='拉丁 mollis → mollificare → 法语 mollifier 等 → mollify；emollire → emolliens／emollient- → emollient；molluscus → 新拉丁 Mollusca → 法语 mollusque → mollusc。',intro='mollify 常说把生气的人安抚下来；emollient 可说柔润皮肤的产品，也可说缓和语气。mollusc 则把柔软用于动物名称，包含蜗牛、蛤蜊和章鱼等。',forms='moll- 软与 mol- 磨不是同一个根。emollient 接拉丁现在分词词干，不能误写成过去分词；mollusk 是 mollusc 的美式拼法。',branches=[['软化态度','mollify'],['柔润皮肤与缓和话语','emollient'],['软体动物','mollusc']],contrasts='mollify 不保证问题已经解决，可能只是把怒气压下。软体动物不要求都有外壳，也不能把一切摸起来软的动物都叫 molluscs。emollient 与乳化剂 emulsifier 的来源不同。',practice='把一段安抚顾客的情景写成 mollify，再用 emollient 描述回复的语气；列出一个有壳和一个没有外壳的 mollusc。',words=rootwords(272),exclude=rootexclude(272))
SINU_ROOT=dict(id='C1349',meaning='弯曲；褶；湾；凹处',core='一条线弯进去，可以形成转折，也可以围出一个凹处。',image='拉丁 sinus → sinuare、insinuare → insinuate；insinuatio 独立借入 → insinuation；sinuosus → sinuous；医学 sinus → sinus、sinusitis；阿拉伯数学译名经中世纪拉丁 sinus → sine，complementi sinus → cosine。',intro='insinuate 像话语绕着说，不直说却让人听出暗示；sinuous 描写连续弯曲；sinus 是解剖中的腔隙名称。sine 的数学义有跨语言翻译的历史，不能只用一张波浪形的联想代替。原表“画线”的释义太窄，这里按拉丁 sinus 的实际范围理解。',forms='insinuate 与 sinuous 中常听见 /sɪnju/，sinus 与 sine 却是 /saɪ/。cosine 中 co- 联系 complement 余角，不是简单的共同、一起；insinuation 不是一定晚于英语 insinuate 的新造名词。',branches=[['绕着说与慢慢挤入','insinuate, insinuation, insinuating'],['连续曲线','sinuous'],['身体腔隙','sinus, sinusitis'],['数学译名与余角','sine, cosine']],contrasts='sinus 不只指鼻窦，sine 也不是任何曲线的总称。右三角形的对边比斜边与单位圆纵坐标是正弦的两种相连表述；余弦对应邻边比斜边与横坐标。',practice='用 insinuating 描写一句带刺的暗示，用 sinuous 描写河流，再说明 sine、cosine 在单位圆上分别看哪一个坐标。',words=rootwords(273,['sinusitis']),exclude=rootexclude(273))
OSTRAC_ROOT=dict(id='C0930',meaning='壳；陶片；由陶片投票发展出的排斥',core='名字写到陶片上，成为决定把谁排除在城邦之外的投票。',image='希腊 ostrakon 壳、陶片 → ostrakizein 放逐；名词 ostrakismos 经拉丁语、法语等 → ostracism；希腊动词形态另进入英语 → ostracize。',intro='ostracism 在历史语境里是陶片放逐，在现代常是群体对一个人的冷落、排斥。ostracize 是把人排除在外的动作；现代公司或朋友圈中的排斥不需要真的举行陶片投票。',forms='英语 ostracism 比 ostracize 更早见于文献，不能因为名词看起来有 -ism 就强画成英语动词在先。ostracise 是英式常见拼法，读音不因 s、z 拼写而改变。',branches=[['排斥这种处境或做法','ostracism'],['把人冷落、排除','ostracize']],contrasts='expel 常是正式驱逐，ostracize 可以完全没有公文，只是大家不再理会。shell 的实物意义是古典起点，不能把现代每个含 ostrac- 的技术名都解释成社会放逐。',practice='用 ostracism 描述一种处境，再用 ostracize 写出谁把谁排除在外；指出古雅典习俗与现代冷落之间保留了什么共同点。',words=rootwords(274),exclude=rootexclude(274))
HISTRI_ROOT=dict(id='C0559',meaning='演员；戏剧化表演',core='一个普通场景，被表现得像舞台上的高潮，情绪动作都放得很大。',image='拉丁 histrio／histrion- 演员 → histrionicus → 晚期拉丁、法语 histrionique 等 → histrionic → histrionics。',intro='histrionic 可以联系表演艺术，现代日常评论却常用来批评反应过头、夸张做作。histrionics 把这类举动当作一整套表现来讲。英语的负面比喻很早就存在，不必排成先有中性戏剧义、后来才批评的单线。',forms='histrion- 是拉丁演员名词的词干，不是 history 历史。histrionics 常以复数形式表示夸张表现，不通常说 a histrionics。',branches=[['夸张或戏剧性的','histrionic'],['一套夸张的表现','histrionics']],contrasts='dramatic 有时只是鲜明、令人印象深刻；histrionic 在普通评价里更容易带做作、过火的贬义。日常词义不等于给一个人下心理诊断。',practice='描述一次小事被大惊小怪处理的情景，分别用 histrionic reaction 和 histrionics，比较形容词与名词如何放进句子。',words=rootwords(275),exclude=rootexclude(275))
TORPE_ROOT=dict(id='C1527',meaning='麻木；迟钝；活动减少',core='像开关暂时拨低，感觉和动作都慢下来。',image='拉丁 torpere → torpidus → torpid；拉丁 torpor 独立借入 → torpor；拉丁 torpedo 麻木、电鳐 → 英语电鳐名 → 水下爆炸装置与鱼雷 → torpedo 破坏计划。',intro='torpid 说迟钝、少活动，torpor 说这种状态；生物学中还能指动物代谢和活动降低的状态。torpedo 的鱼雷义则经过了电鳐这个历史中间站，不能从现代武器的外形直接反推词源。',forms='torpid 与 torpor 是拉丁同源形式分别借入，英语 torpid 不必由 torpor 改尾巴。torpedo 的重音在中间 /piː/，复数常写 torpedoes；动词保留相同读音。',branches=[['迟钝、低活动的性质与状态','torpid, torpor'],['电鳐名称、武器与破坏计划','torpedo']],contrasts='torpor 的生物学用法不等于所有睡眠，也不要求一定持续整个冬天。torpedo a plan 是让计划失败，句子里未必真的有武器。',practice='把一个委员会迟迟不行动的状态写成 torpor，再用 torpedo 描述预算变化毁掉计划；说明两种现代比喻分别经过哪条历史支线。',words=rootwords(276),exclude=rootexclude(276))
PARS_ROOT=dict(id='C0959',meaning='节省；少用；克制',core='能少用一点就少用一点；落在人身上可能是吝啬，落在解释上也可能是简洁。',image='拉丁 parcere → parsimonia／parcimonia → 英语 parsimony；拉丁名词词干或英语 parsimony + 形容词尾 → parsimonious。',intro='parsimony 在钱财语境常说吝啬，在科学语境可以说不额外增加没必要的假设。parsimonious 相应描述人或模型，褒贬由对象和上下文决定。',forms='parc-、pars- 来自拉丁节用词族，不是 pauc- 少或 parvus 小的随意变形。parsimonious 的词典分析可从拉丁名词词干或英语名词说明，不必把单一路线说死。',branches=[['节用、吝啬与解释的简约','parsimony'],['人、预算或模型的性质','parsimonious']],contrasts='frugal 常偏正面节俭，parsimonious 形容人时常有过分省钱的意思。研究中的简约不是越简单越对：仍须解释证据，不能删掉必要因素。',practice='用 parsimonious 分别评价老板和统计模型，解释为什么同一个形容词可以一处批评、一处称许。',words=rootwords(277),exclude=rootexclude(277))
